// The browser-side plant map must be byte-identical to src/plot_svg.py, so the web UI
// shows exactly the picture the Streamlit app (and the downloads) draw.
// Fixtures: python-generated by plot_svg.plant_svg (see the PR that added them).
import { describe, expect, it } from "vitest";
import fixtures from "./plant_svg_fixtures.json";
import { plantSvg } from "../plantSvg";

describe("plantSvg parity with plot_svg.plant_svg", () => {
  for (const c of fixtures as any[]) {
    it(c.name, () => {
      const values: Record<string, number> = {};
      for (const [k, v] of Object.entries(c.values)) values[k] = v === null ? NaN : (v as number);
      const o = c.opts;
      const svg = plantSvg(values, {
        cmin: o.cmin, cmax: o.cmax, cwo: o.cwo ?? null, lang: o.lang,
        grainSignal: o.grainSignal ?? null, unit: o.unit ?? "µg/kg",
      });
      expect(svg).toBe(c.svg);
    });
  }
});
